    {"type": "add_sketch_centerline", "description": "Add a finite dashed centerline through two coordinates.", "required": ["sketch_id", "start", "end"], "optional": [], "constraints": ["Endpoints are distinct finite {x, y} coordinates; excluded from profiles."]},
    {"type": "add_sketch_construction_line", "description": "Add a construction segment through two coordinates.", "required": ["sketch_id", "start", "end"], "optional": [], "constraints": ["Endpoints are distinct finite {x, y} coordinates; excluded from profiles."]},
    {"type": "add_sketch_element", "description": "Add a point, line, circle, or ellipse to a sketch.", "required": ["sketch_id", "element_type"], "optional": ["x", "y", "start_id", "end_id", "center_id", "radius", "center_x", "center_y", "major_radius", "minor_radius", "rotation_radians"], "constraints": ["element_type is point (x,y), line (start_id,end_id), circle (center_id,radius), or ellipse (center_x,center_y,major_radius,minor_radius,rotation_radians). Prefer the atomic geometry commands when possible."]},
