    {"type": "add_sketch_rectangle_two_corners", "description": "Add an axis-aligned rectangle from two opposite corners.", "required": ["sketch_id", "x1", "y1", "x2", "y2"], "optional": [], "constraints": ["Both sides must exceed 1e-7."]},
    {"type": "add_sketch_rectangle_center", "description": "Add an axis-aligned rectangle from its center and dimensions.", "required": ["sketch_id", "center_x", "center_y", "width", "height"], "optional": [], "constraints": ["Width and height must be positive."]},
    {"type": "add_sketch_rectangle_three_points", "description": "Add a rectangle from three consecutive corners.", "required": ["sketch_id", "points"], "optional": [], "constraints": ["Three points must define adjacent perpendicular sides."]},
    {"type": "add_sketch_rotated_rectangle", "description": "Add a rotated rectangle from its center, dimensions, and angle.", "required": ["sketch_id", "center_x", "center_y", "width", "height", "angle_degrees"], "optional": [], "constraints": ["Width and height must be positive finite numbers."]},
    {"type": "add_sketch_parallelogram", "description": "Add a parallelogram from three consecutive corners.", "required": ["sketch_id", "points"], "optional": [], "constraints": ["Three points must be non-collinear."]},
