    {"type": "add_sketch_circle_two_points", "description": "Add a circle whose diameter is defined by two points.", "required": ["sketch_id", "first", "second"], "optional": [], "constraints": ["The points must be distinct."]},
    {"type": "add_sketch_circle_three_points", "description": "Add a circle through three points.", "required": ["sketch_id", "first", "second", "third"], "optional": [], "constraints": ["The points must be distinct and non-collinear."]},
