    {"type": "add_sketch_circle_tangent_to_two_lines", "description": "Add a circle tangent to two sketch lines.", "required": ["sketch_id", "first_line_id", "second_line_id", "radius"], "optional": ["first_side", "second_side"], "constraints": ["Sides are 1 or -1 relative to each line direction; both tangency points must lie on finite segments; parallel lines are rejected."]},
    {"type": "add_sketch_circle_tangent_to_three_lines", "description": "Add a circle tangent to three sketch lines.", "required": ["sketch_id", "first_line_id", "second_line_id", "third_line_id"], "optional": ["first_side", "second_side", "third_side"], "constraints": ["The three sides select the tangent solution; its radius is solved from the lines; all contacts must lie on finite segments."]},
    {"type": "add_sketch_arc_center", "description": "Add an exact circular arc from center, start and end points.", "required": ["sketch_id", "center", "start", "end"], "optional": ["clockwise"], "constraints": ["Start and end must have the same positive radius; counterclockwise is the default direction."]},
    {"type": "add_sketch_arc_three_points", "description": "Add an exact circular arc through start, intermediate and end points.", "required": ["sketch_id", "start", "through", "end"], "optional": [], "constraints": ["Points must be distinct and non-collinear; the sweep passes through the intermediate point."]},
    {"type": "add_sketch_arc_start_center_end", "description": "Add an exact circular arc from start, center and end points.", "required": ["sketch_id", "start", "center", "end"], "optional": ["clockwise"], "constraints": ["Start and end must be distinct and have the same positive radius from center."]},
    {"type": "add_sketch_arc_radius", "description": "Add an exact circular arc from endpoints and radius.", "required": ["sketch_id", "start", "end", "radius"], "optional": ["large_arc", "clockwise"], "constraints": ["Endpoint distance must not exceed the diameter; large_arc and clockwise select the solution."]},
    {"type": "add_sketch_arc_tangent", "description": "Add an exact circular arc tangent to a sketch line at a supplied point.", "required": ["sketch_id", "line_id", "tangent_point", "radius", "sweep_degrees"], "optional": ["side"], "constraints": ["The tangent point must lie on the line; side is 1 or -1; sweep is signed, non-zero and under 360 degrees."]},
