    {"type": "add_sketch_circumscribed_polygon", "description": "Add a regular polygon tangent to the supplied incircle.", "required": ["sketch_id", "center_x", "center_y", "side_count", "radius"], "optional": ["rotation_degrees"], "constraints": ["3–512 sides; radius is the inradius."]},
    {"type": "add_sketch_polygon_from_center", "description": "Add a regular polygon from its center and first vertex.", "required": ["sketch_id", "center_x", "center_y", "first_vertex", "side_count"], "optional": [], "constraints": ["3–512 sides; first_vertex must differ from the center."]},
